/// <summary>
/// VM - CB264 - Pickupslot
/// Table to store the Split category code with area.
/// </summary>
public class METOrderSplitCategoryArea extends common
{
}

Method.Source:
    /// <summary>
    /// find unique record
    /// </summary>
    /// <param name = "_currentCategory">_currentCategory</param>
    /// <param name = "_area">_area</param>
    /// <param name = "_newCategory">_newCategory</param>
    /// <param name = "update">update</param>
    /// <returns>METOrderSplitCategoryArea</returns>
    static METOrderSplitCategoryArea find(METCategoryCode _currentCategory, METSlotArea _area, METCategoryCode _newCategory, boolean update = false)
    {
        METOrderSplitCategoryArea metOrderSplitCategoryArea;
        
        if (_currentCategory && _area && _newCategory)
        {
            select firstonly metOrderSplitCategoryArea
                    index hint SplitCategoryIdx
                where metOrderSplitCategoryArea.currentCategory == _currentCategory
                    && metOrderSplitCategoryArea.Area == _area 
                    && metOrderSplitCategoryArea.NewCategory == _newCategory;

            metOrderSplitCategoryArea.selectForUpdate(update);
        }
        return metOrderSplitCategoryArea;
    }

/// <summary>
/// Exist record
/// </summary>
/// <param name = "_currentCategory">_currentCategory</param>
/// <param name = "_area">_area</param>
/// <param name = "_newCategory">_newCategory</param>
/// <returns>boolean</returns>
public static boolean exist(METCategoryCode _currentCategory, METSlotArea _area, METCategoryCode _newCategory)
{
    return _currentCategory && _area && _newCategory && (select firstonly RecId from METOrderSplitCategoryArea
                                                                index hint SplitCategoryIdx
                                                                where METOrderSplitCategoryArea.currentCategory == _currentCategory
                                                                && metOrderSplitCategoryArea.Area == _area
                                                                && metOrderSplitCategoryArea.NewCategory == _newCategory).RecId != 0;
}

    /// <summary>
    /// Assign value to New category
    /// </summary>
    /// <param name = "_fieldId">_fieldId</param>
    public void modifiedField(fieldId _fieldId)
    {
        switch(_fieldId)
        {
            case fieldnum(METOrderSplitCategoryArea, CurrentCategory):
            case fieldnum(METOrderSplitCategoryArea, Area):
                this.NewCategory = this.CurrentCategory + METConstants::hyphen + this.Area;
                break;

            default:
                super(_fieldId);
        }
    }
